  add column pending_submitted_at timestamptz;

alter type public.notification_type add value if not exists 'farmer_profile_update';

-- ===== 023_atomic_checkout_and_cancel_cascade.sql =====
-- ---------------------------------------------------------------------------
-- Fix 1: atomic checkout to eliminate the stock overselling race.
--
-- The previous flow validated stock, then created the order/items/payment,
-- then decremented stock as a best-effort step afterwards (errors were only
-- logged). Two concurrent checkouts for the last unit of a product could
-- both pass validation and both get a successful order, overselling the
-- product. place_order() does everything — product lock, validation,
-- pricing, order/items/payment insert, stock decrement — inside a single
-- transaction. Any stock shortfall raises an exception and the whole
-- transaction rolls back, so no order is ever created without real stock
-- backing it.
-- ---------------------------------------------------------------------------
create or replace function public.place_order(
  p_customer_id uuid,
  p_contact_phone text,
  p_delivery_address_text text,
  p_bank_id uuid,
  p_receipt_url text,
  p_delivery_fee numeric,
  p_items jsonb
)
returns table (order_id uuid, order_code text)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order_id uuid;
  v_order_code text;
  v_subtotal numeric := 0;
  v_total numeric := 0;
  v_item jsonb;
  v_product record;
  v_quantity numeric;
  v_unit_price numeric;
  v_line_total numeric;
  v_farmer_ids uuid[] := '{}';
  v_product_ids uuid[] := '{}';
  v_titles text[] := '{}';
  v_quantities numeric[] := '{}';
  v_unit_types public.unit_type[] := '{}';
  v_unit_prices numeric[] := '{}';
  v_line_totals numeric[] := '{}';
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_CART';
  end if;

  -- Lock every involved product row up front, in a stable (id-sorted) order,
  -- so two concurrent checkouts touching an overlapping cart can't deadlock.
  perform 1
  from public.products
  where id in (
    select (value ->> 'product_id')::uuid
    from jsonb_array_elements(p_items)
  )
  order by id
  for update;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_quantity := (v_item ->> 'quantity')::numeric;
    if v_quantity is null or v_quantity <= 0 then
      raise exception 'INVALID_QUANTITY';
    end if;

    select id, farmer_id, title, unit_type, final_price, farmer_price,
           quantity_available, in_stock, status
      into v_product
      from public.products
      where id = (v_item ->> 'product_id')::uuid;

    if not found then
      raise exception 'PRODUCT_NOT_FOUND';
    end if;

    if v_product.status <> 'approved' then
      raise exception 'PRODUCT_NOT_FOUND';
    end if;

    if not v_product.in_stock or v_product.quantity_available < v_quantity then
      raise exception 'OUT_OF_STOCK:%', v_product.title;
    end if;

    v_unit_price := coalesce(v_product.final_price, v_product.farmer_price);
    v_line_total := v_unit_price * v_quantity;
    v_subtotal := v_subtotal + v_line_total;

    v_farmer_ids := v_farmer_ids || v_product.farmer_id;
    v_product_ids := v_product_ids || v_product.id;
    v_titles := v_titles || v_product.title;
    v_quantities := v_quantities || v_quantity;
    v_unit_types := v_unit_types || v_product.unit_type;
    v_unit_prices := v_unit_prices || v_unit_price;
    v_line_totals := v_line_totals || v_line_total;

    update public.products
      set quantity_available = quantity_available - v_quantity,
          in_stock = (quantity_available - v_quantity) > 0
      where id = v_product.id;
  end loop;

  v_total := v_subtotal + p_delivery_fee;
  v_order_code := public.generate_order_code();

  insert into public.orders
    (order_code, customer_id, contact_phone, delivery_address_text,
     subtotal, delivery_fee, total_amount, status)
  values
    (v_order_code, p_customer_id, p_contact_phone, p_delivery_address_text,
     v_subtotal, p_delivery_fee, v_total, 'awaiting_confirmation')
  returning id into v_order_id;

  insert into public.order_items
    (order_id, farmer_id, product_id, product_title, quantity, unit_type,
     unit_price, line_total, status)
  select v_order_id, f, p, t, q, u, up, lt, 'new'
  from unnest(
    v_farmer_ids, v_product_ids, v_titles, v_quantities,
    v_unit_types, v_unit_prices, v_line_totals
  ) as x(f, p, t, q, u, up, lt);

  insert into public.payments (order_id, bank_id, receipt_url, status)
  values (v_order_id, p_bank_id, p_receipt_url, 'pending');

  insert into public.order_status_events (order_id, status, changed_by, note)
  values (v_order_id, 'awaiting_confirmation', p_customer_id, 'Sifariş yaradıldı');

  return query select v_order_id, v_order_code;
end;
$$;

grant execute on function public.place_order(
  uuid, text, text, uuid, text, numeric, jsonb
) to authenticated;

-- ---------------------------------------------------------------------------
-- Fix 2: cancelling an order left its order_items stuck on their old status
-- (e.g. "new"/"preparing"), so a farmer's dashboard kept showing a cancelled
-- order's items as active work. Add a terminal 'cancelled' item status and a
-- trigger that cascades it automatically whenever an order is cancelled,
-- regardless of which code path did the cancelling. Already-delivered items
-- are left alone — cancellation shouldn't rewrite completed history.
-- ---------------------------------------------------------------------------
alter type public.order_item_status add value if not exists 'cancelled';

-- ===== 024_cancel_cascade_trigger.sql =====
-- ---------------------------------------------------------------------------
-- Cascades order cancellation to its order_items automatically, so a
-- farmer's dashboard stops showing a cancelled order's items as active
-- work. Fires no matter which code path cancels the order (payment
-- rejection, admin status change, or anything added later). Already
-- delivered items are left untouched.
--
-- Split into its own migration because Postgres won't let a new enum value
-- (order_item_status.cancelled, added in 023) be referenced in the same
-- transaction that added it.
-- ---------------------------------------------------------------------------
create or replace function public.cascade_cancel_order_items()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.order_items
  set status = 'cancelled'
  where order_id = new.id
    and status not in ('delivered', 'cancelled');
  return new;
end;
$$;

drop trigger if exists orders_cancel_cascade on public.orders;

create trigger orders_cancel_cascade
after update of status on public.orders
for each row
when (new.status = 'cancelled' and old.status is distinct from 'cancelled')
execute function public.cascade_cancel_order_items();

-- ===== 025_restore_stock_on_cancel.sql =====
-- ---------------------------------------------------------------------------
-- Cancelling an order (payment rejection or admin status change) decremented
-- stock at checkout time but never gave it back — cancelled orders
-- permanently shrank inventory even though nothing was ever shipped.
-- Extends the cascade trigger from 024 (same automatic-on-any-cancellation
-- guarantee) to also restore quantity_available/in_stock for every item
-- actually moving to cancelled. Already-delivered items are excluded, same
-- as the status cascade — that stock was genuinely sold.
-- ---------------------------------------------------------------------------
create or replace function public.cascade_cancel_order_items()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.products p
  set quantity_available = p.quantity_available + oi.quantity,
      in_stock = true
  from public.order_items oi
  where oi.order_id = new.id
    and oi.status not in ('delivered', 'cancelled')
    and oi.product_id = p.id;

  update public.order_items
  set status = 'cancelled'
  where order_id = new.id
    and status not in ('delivered', 'cancelled');

  return new;
end;
$$;

-- ===== 026_courier_assignment.sql =====
-- ---------------------------------------------------------------------------
-- No order was ever assigned to a specific courier — RLS let ANY active
-- courier update ANY order, so two couriers opening the queue at the same
-- moment could both "pick up" the same order (double-processing, duplicate
-- customer notifications, no accountability for who actually has it).
--
-- Adds orders.courier_id, claimed on the courier's first action (moving an
-- order to "picked_up"). Once claimed, RLS only lets that same courier
-- (or an admin) touch the order — a second courier's claim attempt affects
-- zero rows instead of racing the first one.
-- ---------------------------------------------------------------------------
alter table public.orders
  add column courier_id uuid references public.couriers (id) on delete set null;

create index orders_courier_id_idx on public.orders (courier_id);

create or replace function public.my_courier_id()
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select id from public.couriers where profile_id = auth.uid();
$$;

drop policy if exists "Admins and couriers update orders" on public.orders;

create policy "Admins and couriers update orders"
on public.orders for update
using (
  public.is_admin()
  or (
    public.is_courier()
    and (courier_id is null or courier_id = public.my_courier_id())
  )
)
with check (
  public.is_admin()
  or (
    public.is_courier()
    and (courier_id is null or courier_id = public.my_courier_id())
  )
);

-- ===== 027_protect_order_history_on_farmer_delete.sql =====
-- ---------------------------------------------------------------------------
-- order_items.farmer_id was ON DELETE CASCADE, so hard-deleting a farmer
-- (deleteFarmer) silently destroyed the line items of every order they
-- were ever part of — including already-delivered, paid orders, not just
-- pending ones. Order totals stayed on the parent `orders` row with no
-- items left to explain them.
--
-- deleteFarmer already has a friendly error message anticipating exactly
-- this ("Sifariş tarixçəsi ... mane ola bilər") — it was dead code because
-- CASCADE meant the delete always succeeded. Switching this FK to RESTRICT
-- makes that guard real: deleting a farmer with any order history now fails
-- cleanly, and the admin is pointed at Deactivate/Suspend instead, which
-- already leaves products/orders untouched.
-- ---------------------------------------------------------------------------
alter table public.order_items
  drop constraint order_items_farmer_id_fkey,
  add constraint order_items_farmer_id_fkey
    foreign key (farmer_id) references public.farmers (id) on delete restrict;

-- ===== 028_hero_content.sql =====
-- Seed editable Hero (homepage) content for the admin Hero panel

insert into public.site_content (key, title, body, items)
values (
  'hero',
  'Fermerdən,',
  'Mövsümi məhsulları birbaşa yerli fermerlərdən kəşf edin. Daha sağlam qidalanaraq icmanızı dəstəkləyin.',
  '{
    "highlight": "birbaşa süfrənizə.",
    "imageUrl": "https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=2400&q=80"
  }'::jsonb
)
on conflict (key) do nothing;

-- ===== 029_category_submission_notification_type.sql =====
-- ---------------------------------------------------------------------------
-- New category/subcategory proposals from a farmer notified admins with
-- type "general" — the same generic type used for unrelated, non-actionable
-- notifications (e.g. "farmer updated order item status"). That made it
-- impossible to give category-approval notifications their own red
-- "needs review" styling without also flagging unrelated general
-- notifications. Give it its own type instead.
-- ---------------------------------------------------------------------------
alter type public.notification_type
  add value if not exists 'category_submission';

-- ===== 030_auth_image_content.sql =====
-- Seed editable sign-in/sign-up page image + text for the admin Hero panel

insert into public.site_content (key, title, body, items)
values (
  'auth_image',
  'Fermerdən,',
  'Yerli fermerlərdən təzə məhsulları kəşf edin, sifariş verin və icmanızı dəstəkləyin.',
  '{
    "highlight": "birbaşa süfrənizə.",
    "imageUrl": "/hero/kend.jpg"
  }'::jsonb
)
on conflict (key) do nothing;

-- ===== 031_receipt_limit_and_folder_policy.sql =====
-- Receipts now upload straight from the browser to Storage (the Server Action
-- only receives the path), so the 5 MB cap no longer has to sit under the
-- request-body limit. Raise it to 7 MB to match RECEIPT_MAX_BYTES.
update storage.buckets
set file_size_limit = 7340032
where id = 'payment-receipts';

-- The browser can now write to this bucket directly, so pin every upload to
-- the uploader's own folder (<user id>/<file>). place_order is only ever
-- handed paths inside that folder, and the server re-checks it.
drop policy if exists "Customers upload payment receipts" on storage.objects;

create policy "Customers upload payment receipts"
on storage.objects for insert
with check (
  bucket_id = 'payment-receipts'
  and auth.uid() is not null
  and (storage.foldername(name))[1] = auth.uid()::text
);

-- ===== 032_product_images_folder_policy.sql =====
-- Farmers' product photos now upload straight from the browser to Storage
-- (the Server Action only receives their paths), so pin those uploads to the
-- uploader's own folder (<user id>/uploads/<file>). Admins keep writing the
-- shared site folders (hero/, auth/, categories/) from server actions.
drop policy if exists "Farmers upload product images" on storage.objects;

create policy "Farmers upload product images"
on storage.objects for insert
with check (
  bucket_id = 'product-images'
  and auth.uid() is not null
  and (
    (storage.foldername(name))[1] = auth.uid()::text
    or public.is_admin()
  )
);

-- ===== 033_farmer_media_folder_policy.sql =====
-- Farmers' post photos and videos now upload straight from the browser to
-- Storage (the Server Action only receives their paths), so pin every upload
-- to the uploader's own folder. Avatars already live under <user id>/avatar/
-- and post media under <user id>/posts/, so nothing legitimate is affected.
drop policy if exists "Farmers upload farmer media" on storage.objects;

create policy "Farmers upload farmer media"
on storage.objects for insert
with check (
  bucket_id = 'farmer-media'
  and auth.uid() is not null
  and (storage.foldername(name))[1] = auth.uid()::text
);

-- ===== 034_sync_product_in_stock.sql =====
-- ---------------------------------------------------------------------------
-- in_stock is derived from quantity_available, but nothing enforced that: it
-- was kept in sync by hand in place_order(), the cancel-restore trigger and
-- the farmer product actions. Any path that forgot (or a manual SQL edit)
-- could leave in_stock = true with quantity_available = 0, which makes a
-- sold-out product look available in the shop listings.
--
-- A trigger makes the two impossible to disagree, whoever writes the row.
-- ---------------------------------------------------------------------------

create or replace function public.sync_product_in_stock()
returns trigger
language plpgsql
as $$
begin
  new.in_stock := new.quantity_available > 0;
  return new;
end;
$$;

drop trigger if exists products_sync_in_stock on public.products;

create trigger products_sync_in_stock
before insert or update of quantity_available, in_stock on public.products
for each row execute function public.sync_product_in_stock();

-- Fix any row that already drifted.
update public.products
set in_stock = quantity_available > 0
where in_stock is distinct from (quantity_available > 0);

-- ===== 035_product_archived_status.sql =====
-- ---------------------------------------------------------------------------
-- Lets a farmer take a product off sale without deleting it.
--
-- Deleting was never an option: order_items.product_id is ON DELETE CASCADE,
-- so removing a product would also wipe it out of every past order, breaking
-- the customer's and the farmer's order history (the same reason farmer
-- deletion was already protected in migration 027).
--
-- An "archived" status keeps the row — and therefore the order history —
-- while every public query already filters on status = 'approved', so the
-- product disappears from the shop, search, farmer profile, cart and
-- place_order() without any further change.
-- ---------------------------------------------------------------------------

alter type public.product_status add value if not exists 'archived';

-- ===== 036_product_reviews.sql =====
-- ---------------------------------------------------------------------------
-- Real customer reviews, replacing the hard-coded ones on the product page.
--
-- A review may only be written by someone who actually received the product:
-- the insert policy requires a delivered order_item for that product and that
-- customer. That rule lives in RLS, not just in the UI, so it also holds for
-- anything talking to the API directly.
-- ---------------------------------------------------------------------------

create table if not exists public.product_reviews (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  customer_id uuid not null references public.profiles (id) on delete cascade,
  rating smallint not null check (rating between 1 and 5),
  comment text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- One review per customer per product; writing again updates it.
  unique (product_id, customer_id)
);

create index if not exists product_reviews_product_id_idx
  on public.product_reviews (product_id);

drop trigger if exists product_reviews_set_updated_at on public.product_reviews;
create trigger product_reviews_set_updated_at
before update on public.product_reviews
for each row execute function public.set_updated_at();

alter table public.product_reviews enable row level security;

-- Reviews are public: they are shown to everyone on the product page.
drop policy if exists "Reviews are public" on public.product_reviews;
create policy "Reviews are public"
on public.product_reviews for select
using (true);

-- Only a customer who actually received this product may review it.
drop policy if exists "Buyers write own reviews" on public.product_reviews;
create policy "Buyers write own reviews"
on public.product_reviews for insert
with check (
  customer_id = auth.uid()
  and exists (
    select 1
    from public.order_items oi
    join public.orders o on o.id = oi.order_id
    where oi.product_id = product_reviews.product_id
      and o.customer_id = auth.uid()
      and oi.status = 'delivered'::public.order_item_status
  )
);

drop policy if exists "Customers update own reviews" on public.product_reviews;
create policy "Customers update own reviews"
on public.product_reviews for update
using (customer_id = auth.uid())
with check (customer_id = auth.uid());

-- A customer can remove their own review; an admin can moderate any of them.
drop policy if exists "Customers or admins delete reviews" on public.product_reviews;
create policy "Customers or admins delete reviews"
on public.product_reviews for delete
using (customer_id = auth.uid() or public.is_admin());

-- ---------------------------------------------------------------------------
-- The reviewer's name lives in profiles, which RLS only exposes to its owner
-- and admins — so a plain join would return nothing for other visitors. Same
-- approach as list_approved_farmer_owner_names (migration 021): a narrow
-- security-definer function that exposes just the name alongside the review.
-- ---------------------------------------------------------------------------
create or replace function public.list_product_reviews(p_product_id uuid)
returns table (
  id uuid,
  customer_id uuid,
  customer_name text,
  rating smallint,
  comment text,
  created_at timestamptz
)
language sql
security definer
set search_path = public, pg_temp
stable
as $$
  select r.id, r.customer_id, p.full_name as customer_name,
         r.rating, r.comment, r.created_at
  from public.product_reviews r
  join public.profiles p on p.id = r.customer_id
  where r.product_id = p_product_id
  order by r.created_at desc
  limit 50;
$$;

grant execute on function public.list_product_reviews(uuid) to anon, authenticated;

-- ===== 037_farmer_cover_and_certificates.sql =====
-- ---------------------------------------------------------------------------
-- Farmer profile redesign: a cover photo, a certificates section and a real
-- farmer rating.
-- ---------------------------------------------------------------------------

-- Cover photo. Like the avatar, a new cover is staged in pending_cover_url
-- and only goes live once an admin approves the profile edit.
alter table public.farmers
  add column if not exists cover_url text,
  add column if not exists pending_cover_url text;

-- Certificates (organic, quality, etc.) a farmer shows on their profile.
-- The file is a photo or a PDF in the farmer-media bucket, under
-- <user id>/certificates/.
create table if not exists public.farmer_certificates (
  id uuid primary key default gen_random_uuid(),
  farmer_id uuid not null references public.farmers (id) on delete cascade,
  title text not null check (char_length(title) between 1 and 120),
  file_url text not null,
  file_type text not null check (file_type in ('image', 'pdf')),
  created_at timestamptz not null default now()
);

create index if not exists farmer_certificates_farmer_id_idx
  on public.farmer_certificates (farmer_id, created_at desc);

alter table public.farmer_certificates enable row level security;

-- Public for approved farmers, like the rest of their profile.
drop policy if exists "Certificates are public for approved farmers" on public.farmer_certificates;
create policy "Certificates are public for approved farmers"
on public.farmer_certificates for select
using (
  exists (
    select 1 from public.farmers f
    where f.id = farmer_certificates.farmer_id
      and (
        f.status = 'approved'::public.farmer_status
        or f.profile_id = auth.uid()
      )
  )
  or public.is_admin()
);

drop policy if exists "Approved farmers add own certificates" on public.farmer_certificates;
create policy "Approved farmers add own certificates"
on public.farmer_certificates for insert
with check (
  exists (
    select 1 from public.farmers f
    where f.id = farmer_certificates.farmer_id
      and f.profile_id = auth.uid()
      and f.status = 'approved'::public.farmer_status
  )
);

drop policy if exists "Farmers or admins delete certificates" on public.farmer_certificates;
create policy "Farmers or admins delete certificates"
on public.farmer_certificates for delete
using (
  exists (
    select 1 from public.farmers f
    where f.id = farmer_certificates.farmer_id
      and f.profile_id = auth.uid()
  )
  or public.is_admin()
);

-- Certificates are often PDFs; the bucket only took images and video.
update storage.buckets
set allowed_mime_types = array_append(allowed_mime_types, 'application/pdf')
where id = 'farmer-media'
  and not ('application/pdf' = any (allowed_mime_types));

-- ---------------------------------------------------------------------------
-- The farmer's rating: the average of every review on their products.
-- Security definer so reviews on products a visitor can no longer see
-- (archived, sold out) still count.
-- ---------------------------------------------------------------------------
create or replace function public.farmer_rating_summary(p_farmer_id uuid)
returns table (average numeric, total integer)
language sql
security definer
set search_path = public, pg_temp
stable
as $$
  select round(avg(r.rating)::numeric, 1), count(*)::integer
  from public.product_reviews r
  join public.products p on p.id = r.product_id
  where p.farmer_id = p_farmer_id;
$$;

grant execute on function public.farmer_rating_summary(uuid) to anon, authenticated;

-- ===== 038_page_view_stats.sql =====
-- ---------------------------------------------------------------------------
-- Site statistics for the admin panel: one row per page view.
--
-- Anonymous by design: no user id and no IP address is stored. A visitor is
-- a random id kept in the browser, so unique visitors can be counted without
-- knowing who they are. Rows older than 21 days are deleted.
-- ---------------------------------------------------------------------------

create table if not exists public.page_views (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  path text not null check (char_length(path) between 1 and 300),
  referrer_host text,
  country text,
  region text,
  city text,
  device text not null default 'desktop'
    check (device in ('mobile', 'tablet', 'desktop', 'other')),
  browser text,
  os text,
  visitor_id uuid,
  is_authenticated boolean not null default false,
  viewer_role text
);

create index if not exists page_views_created_at_idx
  on public.page_views (created_at);

-- No policies: only the server (service role) writes rows, and admins read
-- them through admin_page_view_stats below.
alter table public.page_views enable row level security;

-- ---------------------------------------------------------------------------
-- 21-day retention.
-- ---------------------------------------------------------------------------
create or replace function public.purge_old_page_views()
returns integer
language sql
security definer
set search_path = public, pg_temp
as $$
  with deleted as (
    delete from public.page_views
    where created_at < now() - interval '21 days'
    returning 1
  )
  select count(*)::integer from deleted;
$$;

revoke execute on function public.purge_old_page_views() from public, anon, authenticated;
grant execute on function public.purge_old_page_views() to service_role;

-- Daily clean-up with pg_cron where it is available. The stats function and
-- the tracking endpoint also purge, so retention holds even without it.
do $$
begin
  create extension if not exists pg_cron;
exception when others then
  raise notice 'pg_cron is not available: %', sqlerrm;
end
$$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('purge-page-views', '17 0 * * *', 'select public.purge_old_page_views()');
  end if;
exception when others then
  raise notice 'Could not schedule purge-page-views: %', sqlerrm;
end
$$;

-- ---------------------------------------------------------------------------
-- Everything the admin "Statistika" page shows, for the last p_days days
-- (1 = today only), counted in Baku time.
-- ---------------------------------------------------------------------------
create or replace function public.admin_page_view_stats(p_days integer)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_days integer := least(greatest(coalesce(p_days, 7), 1), 21);
  v_today date := (now() at time zone 'Asia/Baku')::date;
  v_first_day date := v_today - (v_days - 1);
  v_from timestamptz := v_first_day::timestamp at time zone 'Asia/Baku';
  v_result jsonb;
begin
  if not public.is_admin() then
    raise exception 'Only admins can read site statistics' using errcode = '42501';
  end if;

  perform public.purge_old_page_views();

  with v as (
    select * from public.page_views where created_at >= v_from
  )
  select jsonb_build_object(
    'days', v_days,
    'views', (select count(*) from v),
    'visitors', (select count(distinct visitor_id) from v),
    'signed_in_views', (select count(*) from v where is_authenticated),
    'daily', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'day', d.day::date,
        'views', coalesce(c.views, 0),
        'visitors', coalesce(c.visitors, 0)
      ) order by d.day), '[]'::jsonb)
      from generate_series(v_first_day, v_today, interval '1 day') as d(day)
      left join (
        select (created_at at time zone 'Asia/Baku')::date as day,
               count(*) as views,
               count(distinct visitor_id) as visitors
        from v group by 1
      ) c on c.day = d.day::date
    ),
    'hourly', (
      select jsonb_agg(jsonb_build_object('hour', h, 'views', coalesce(c.views, 0)) order by h)
      from generate_series(0, 23) as h
      left join (
        select extract(hour from created_at at time zone 'Asia/Baku')::integer as hour,
               count(*) as views
        from v group by 1
      ) c on c.hour = h
    ),
    'pages', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'views', views) order by views desc), '[]'::jsonb)
      from (select path as label, count(*) as views from v group by 1 order by 2 desc limit 10) t
    ),
    'countries', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'views', views) order by views desc), '[]'::jsonb)
      from (select country as label, count(*) as views from v group by 1 order by 2 desc limit 10) t
    ),
    'cities', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'country', country, 'views', views) order by views desc), '[]'::jsonb)
      from (select city as label, country, count(*) as views from v group by 1, 2 order by 3 desc limit 10) t
    ),
    'devices', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'views', views) order by views desc), '[]'::jsonb)
      from (select device as label, count(*) as views from v group by 1) t
    ),
    'browsers', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'views', views) order by views desc), '[]'::jsonb)
      from (select browser as label, count(*) as views from v group by 1 order by 2 desc limit 8) t
    ),
    'os', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'views', views) order by views desc), '[]'::jsonb)
      from (select os as label, count(*) as views from v group by 1 order by 2 desc limit 8) t
    ),
    'referrers', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'views', views) order by views desc), '[]'::jsonb)
      from (select referrer_host as label, count(*) as views from v group by 1 order by 2 desc limit 10) t
    ),
    'roles', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'views', views) order by views desc), '[]'::jsonb)
      from (select viewer_role as label, count(*) as views from v group by 1) t
    )
  )
  into v_result;

  return v_result;
end;
$$;

revoke execute on function public.admin_page_view_stats(integer) from public, anon;
grant execute on function public.admin_page_view_stats(integer) to authenticated;

-- ===== 039_site_reviews.sql =====
-- ---------------------------------------------------------------------------
-- Customer reviews of Barakatly itself, for the home page.
--
-- Only a customer with at least one delivered order may write one, one per
-- customer (writing again edits it). Nothing reaches the home page until an
-- admin approves it, and an edited review goes back to waiting.
-- The public name is "First L." taken from the profile, never typed in.
-- ---------------------------------------------------------------------------

create table if not exists public.site_reviews (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null unique references public.profiles (id) on delete cascade,
  rating smallint not null check (rating between 1 and 5),
  comment text not null check (char_length(comment) between 10 and 500),
  city text not null check (char_length(city) between 1 and 60),
  display_name text not null default '',
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'hidden')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists site_reviews_status_idx
  on public.site_reviews (status, updated_at desc);

-- "Nərgiz Həsənova" -> "Nərgiz H."; a single name stays as it is.
create or replace function public.short_display_name(p_full_name text)
returns text
language sql
immutable
as $$
  select case
    when coalesce(btrim(p_full_name), '') = '' then 'Müştəri'
    when array_length(regexp_split_to_array(btrim(p_full_name), '\s+'), 1) = 1
      then btrim(p_full_name)
    else split_part(btrim(p_full_name), ' ', 1) || ' ' ||
      upper(left((regexp_split_to_array(btrim(p_full_name), '\s+'))[
        array_length(regexp_split_to_array(btrim(p_full_name), '\s+'), 1)
      ], 1)) || '.'
  end;
$$;

-- Fills in the public name and keeps customers from approving themselves:
-- any change by a non-admin puts the review back to "pending".
create or replace function public.site_reviews_before_write()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if public.is_admin() then
    if tg_op = 'UPDATE'
       and (new.rating, new.comment, new.city) is distinct from (old.rating, old.comment, old.city) then
      new.updated_at := now();
    end if;
    return new;
  end if;

  select public.short_display_name(p.full_name)
    into new.display_name
    from public.profiles p
   where p.id = new.customer_id;

  new.status := 'pending';
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists site_reviews_before_write on public.site_reviews;
create trigger site_reviews_before_write
before insert or update on public.site_reviews
for each row execute function public.site_reviews_before_write();

alter table public.site_reviews enable row level security;

drop policy if exists "Approved site reviews are public" on public.site_reviews;
create policy "Approved site reviews are public"
on public.site_reviews for select
using (status = 'approved' or customer_id = auth.uid() or public.is_admin());

drop policy if exists "Customers with a delivered order write a site review" on public.site_reviews;
create policy "Customers with a delivered order write a site review"
on public.site_reviews for insert
with check (
  customer_id = auth.uid()
  and exists (
    select 1 from public.orders o
    where o.customer_id = auth.uid()
      and o.status = 'delivered'::public.order_status
  )
);

drop policy if exists "Customers edit own site review, admins moderate" on public.site_reviews;
create policy "Customers edit own site review, admins moderate"
on public.site_reviews for update
using (customer_id = auth.uid() or public.is_admin())
with check (customer_id = auth.uid() or public.is_admin());

drop policy if exists "Customers or admins delete site reviews" on public.site_reviews;
create policy "Customers or admins delete site reviews"
on public.site_reviews for delete
using (customer_id = auth.uid() or public.is_admin());

-- ===== 040_product_ratings_and_wishlist.sql =====
-- ---------------------------------------------------------------------------
-- 1. Rating on every product card.
--
-- Product lists would otherwise need every review row to show stars, so each
-- product carries its own average and count, kept up to date by a trigger
-- on product_reviews.
-- ---------------------------------------------------------------------------
alter table public.products
  add column if not exists rating_average numeric(2, 1),
  add column if not exists rating_count integer not null default 0;

create or replace function public.refresh_product_rating(p_product_id uuid)
returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  update public.products p
  set rating_average = s.average,
      rating_count = s.total
  from (
    select round(avg(r.rating)::numeric, 1) as average, count(*)::integer as total
    from public.product_reviews r
    where r.product_id = p_product_id
  ) s
  where p.id = p_product_id;
$$;

revoke execute on function public.refresh_product_rating(uuid) from public, anon, authenticated;

create or replace function public.product_reviews_refresh_rating()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'DELETE' then
    perform public.refresh_product_rating(old.product_id);
  else
    perform public.refresh_product_rating(new.product_id);
    if tg_op = 'UPDATE' then
      if old.product_id <> new.product_id then
        perform public.refresh_product_rating(old.product_id);
      end if;
    end if;
  end if;
  return null;
end;
$$;

drop trigger if exists product_reviews_refresh_rating on public.product_reviews;
create trigger product_reviews_refresh_rating
after insert or update or delete on public.product_reviews
for each row execute function public.product_reviews_refresh_rating();

-- Fill in the reviews written before this migration.
update public.products p
set rating_average = s.average,
    rating_count = s.total
from (
  select product_id, round(avg(rating)::numeric, 1) as average, count(*)::integer as total
  from public.product_reviews
  group by product_id
) s
where p.id = s.product_id;

-- ---------------------------------------------------------------------------
-- 2. Favourites ("Sevimlilər"): products a customer hearted.
-- ---------------------------------------------------------------------------
create table if not exists public.wishlist_items (
  customer_id uuid not null references public.profiles (id) on delete cascade,
  product_id uuid not null references public.products (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (customer_id, product_id)
);

create index if not exists wishlist_items_customer_created_idx
  on public.wishlist_items (customer_id, created_at desc);

alter table public.wishlist_items enable row level security;

drop policy if exists "Customers read own wishlist" on public.wishlist_items;
create policy "Customers read own wishlist"
on public.wishlist_items for select
using (customer_id = auth.uid());

drop policy if exists "Customers add to own wishlist" on public.wishlist_items;
create policy "Customers add to own wishlist"
on public.wishlist_items for insert
with check (customer_id = auth.uid());

drop policy if exists "Customers remove from own wishlist" on public.wishlist_items;
create policy "Customers remove from own wishlist"
on public.wishlist_items for delete
using (customer_id = auth.uid());

-- ===== 041_no_self_follow.sql =====
-- ---------------------------------------------------------------------------
-- A farmer could follow their own farm. Forbid it in the insert policy and
-- remove the self-follows that already exist (they inflated follower counts).
-- ---------------------------------------------------------------------------

delete from public.farmer_follows ff
using public.farmers f
where f.id = ff.farmer_id
  and f.profile_id = ff.follower_id;

drop policy if exists "Customers follow farmers" on public.farmer_follows;
create policy "Customers follow farmers"
on public.farmer_follows for insert
with check (
  follower_id = auth.uid()
  and not exists (
    select 1 from public.farmers f
    where f.id = farmer_follows.farmer_id
      and f.profile_id = auth.uid()
  )
);

-- ===== 042_promo_codes.sql =====
-- ---------------------------------------------------------------------------
-- Promo codes ("Promokodlar").
--
-- The admin creates codes; a customer applies one in the cart. The discount
-- comes off the products' subtotal (never the delivery fee) and is checked
-- again inside place_order(), in the same transaction that creates the
-- order, so the browser can never set its own discount. Farmers' line totals
-- are untouched: the platform carries the discount.
-- ---------------------------------------------------------------------------

create table if not exists public.promo_codes (
  id uuid primary key default gen_random_uuid(),
  -- What the customer types, stored in capitals: "YAY10".
  code text not null unique
    check (code ~ '^[A-Z0-9_-]{3,30}$'),
  -- The admin's own name for it: "Yay kampaniyası".
  name text not null check (char_length(btrim(name)) between 1 and 80),
  discount_type text not null check (discount_type in ('percent', 'fixed')),
  discount_value numeric(10, 2) not null check (discount_value > 0),
  min_order_amount numeric(10, 2) not null default 0 check (min_order_amount >= 0),
  -- The last moment the code works; null = no end date.
  expires_at timestamptz,
  -- Orders that may use it in total; null = no limit.
  max_uses integer check (max_uses is null or max_uses > 0),
  once_per_customer boolean not null default true,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (discount_type <> 'percent' or discount_value <= 100)
);

alter table public.promo_codes enable row level security;

-- Only admins see the list. Customers check a code through check_promo_code(),
-- which says whether it works without revealing the others.
drop policy if exists "Admins manage promo codes" on public.promo_codes;
create policy "Admins manage promo codes"
on public.promo_codes for all
using (public.is_admin())
with check (public.is_admin());

alter table public.orders
  add column if not exists promo_code_id uuid references public.promo_codes (id) on delete set null,
  -- Kept as text too, so an order still says which code it used after the
  -- code itself is deleted.
  add column if not exists promo_code text,
  add column if not exists discount_amount numeric(10, 2) not null default 0
    check (discount_amount >= 0);

create index if not exists orders_promo_code_id_idx
  on public.orders (promo_code_id) where promo_code_id is not null;

-- ---------------------------------------------------------------------------
-- The one place a code is judged. Not callable from the API: it trusts the
-- customer id and subtotal it is given.
--
-- Returns the discount, or an error code:
--   NOT_FOUND, EXPIRED, MIN_ORDER, USED_UP, ALREADY_USED.
-- Cancelled orders don't count as uses.
-- ---------------------------------------------------------------------------
create or replace function public.evaluate_promo_code(
  p_code text,
  p_customer_id uuid,
  p_subtotal numeric,
  p_lock boolean default false
)
returns table (
  promo_id uuid,
  code text,
  name text,
  discount numeric,
  error text,
  min_order_amount numeric
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_promo public.promo_codes%rowtype;
  v_uses integer;
  v_discount numeric;
begin
  if p_lock then
    -- Serialises checkouts using the same code, so the last free use of a
    -- limited code can't be taken twice.
    select * into v_promo from public.promo_codes
      where promo_codes.code = upper(btrim(p_code)) for update;
  else
    select * into v_promo from public.promo_codes
      where promo_codes.code = upper(btrim(p_code));
  end if;

  if not found or not v_promo.is_active then
    return query select null::uuid, upper(btrim(p_code)), null::text, 0::numeric, 'NOT_FOUND', null::numeric;
    return;
  end if;

  if v_promo.expires_at is not null and v_promo.expires_at < now() then
    return query select v_promo.id, v_promo.code, v_promo.name, 0::numeric, 'EXPIRED', null::numeric;
    return;
  end if;

  if p_subtotal < v_promo.min_order_amount then
    return query select v_promo.id, v_promo.code, v_promo.name, 0::numeric, 'MIN_ORDER', v_promo.min_order_amount;
    return;
  end if;

  if v_promo.max_uses is not null then
    select count(*) into v_uses from public.orders o
      where o.promo_code_id = v_promo.id and o.status <> 'cancelled';
    if v_uses >= v_promo.max_uses then
      return query select v_promo.id, v_promo.code, v_promo.name, 0::numeric, 'USED_UP', null::numeric;
      return;
    end if;
  end if;

  if v_promo.once_per_customer and exists (
    select 1 from public.orders o
    where o.promo_code_id = v_promo.id
      and o.customer_id = p_customer_id
      and o.status <> 'cancelled'
  ) then
    return query select v_promo.id, v_promo.code, v_promo.name, 0::numeric, 'ALREADY_USED', null::numeric;
    return;
  end if;

  if v_promo.discount_type = 'percent' then
    v_discount := round(p_subtotal * v_promo.discount_value / 100, 2);
  else
    v_discount := v_promo.discount_value;
  end if;
  -- Never more than the products cost.
  v_discount := least(v_discount, p_subtotal);

  return query select v_promo.id, v_promo.code, v_promo.name, v_discount, null::text, null::numeric;
end;
$$;

revoke execute on function public.evaluate_promo_code(text, uuid, numeric, boolean)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- For the cart and checkout pages: judges a code against the signed-in
-- customer's own cart, priced exactly as place_order() prices it.
-- ---------------------------------------------------------------------------
create or replace function public.check_promo_code(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_customer uuid := auth.uid();
  v_subtotal numeric;
  v_result record;
begin
  if v_customer is null then
    return jsonb_build_object('error', 'NOT_SIGNED_IN');
  end if;

  select coalesce(sum(coalesce(p.final_price, p.farmer_price) * c.quantity), 0)
    into v_subtotal
    from public.cart_items c
    join public.products p on p.id = c.product_id
    where c.customer_id = v_customer
      and c.quantity > 0
      and p.status = 'approved';

  select * into v_result
    from public.evaluate_promo_code(p_code, v_customer, v_subtotal);

  return jsonb_build_object(
    'code', v_result.code,
    'name', v_result.name,
    'discount', v_result.discount,
    'subtotal', v_subtotal,
    'error', v_result.error,
    'min_order_amount', v_result.min_order_amount
  );
end;
$$;

revoke execute on function public.check_promo_code(text) from public, anon;
grant execute on function public.check_promo_code(text) to authenticated;

-- ---------------------------------------------------------------------------
-- place_order() with an optional promo code.
--
-- Also closes two gaps in the old version: it took the customer id and the
-- delivery fee from its caller, so a signed-in user calling the API directly
-- could order in someone else's name or with no delivery fee. Both now come
-- from the session and from here. DELIVERY_FEE in src/lib/checkout/constants.ts
-- must match.
-- ---------------------------------------------------------------------------
drop function if exists public.place_order(uuid, text, text, uuid, text, numeric, jsonb);

create or replace function public.place_order(
  p_contact_phone text,
  p_delivery_address_text text,
  p_bank_id uuid,
  p_receipt_url text,
  p_items jsonb,
  p_promo_code text default null
)
returns table (order_id uuid, order_code text)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  c_delivery_fee constant numeric := 5;
  v_customer_id uuid := auth.uid();
  v_order_id uuid;
  v_order_code text;
  v_subtotal numeric := 0;
  v_discount numeric := 0;
  v_promo_id uuid;
  v_promo_code text;
  v_promo record;
  v_total numeric := 0;
  v_item jsonb;
  v_product record;
  v_quantity numeric;
  v_unit_price numeric;
  v_line_total numeric;
  v_farmer_ids uuid[] := '{}';
  v_product_ids uuid[] := '{}';
  v_titles text[] := '{}';
  v_quantities numeric[] := '{}';
  v_unit_types public.unit_type[] := '{}';
  v_unit_prices numeric[] := '{}';
  v_line_totals numeric[] := '{}';
begin
  if v_customer_id is null then
    raise exception 'NOT_SIGNED_IN';
  end if;

  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_CART';
  end if;

  -- Lock every involved product row up front, in a stable (id-sorted) order,
  -- so two concurrent checkouts touching an overlapping cart can't deadlock.
  perform 1
  from public.products
  where id in (
    select (value ->> 'product_id')::uuid
    from jsonb_array_elements(p_items)
  )
  order by id
  for update;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_quantity := (v_item ->> 'quantity')::numeric;
    if v_quantity is null or v_quantity <= 0 then
      raise exception 'INVALID_QUANTITY';
    end if;

    select id, farmer_id, title, unit_type, final_price, farmer_price,
           quantity_available, in_stock, status
      into v_product
      from public.products
      where id = (v_item ->> 'product_id')::uuid;

    if not found then
      raise exception 'PRODUCT_NOT_FOUND';
    end if;

    if v_product.status <> 'approved' then
      raise exception 'PRODUCT_NOT_FOUND';
    end if;

    if not v_product.in_stock or v_product.quantity_available < v_quantity then
      raise exception 'OUT_OF_STOCK:%', v_product.title;
    end if;

    v_unit_price := coalesce(v_product.final_price, v_product.farmer_price);
    v_line_total := v_unit_price * v_quantity;
    v_subtotal := v_subtotal + v_line_total;

    v_farmer_ids := v_farmer_ids || v_product.farmer_id;
    v_product_ids := v_product_ids || v_product.id;
    v_titles := v_titles || v_product.title;
    v_quantities := v_quantities || v_quantity;
    v_unit_types := v_unit_types || v_product.unit_type;
    v_unit_prices := v_unit_prices || v_unit_price;
    v_line_totals := v_line_totals || v_line_total;

    update public.products
      set quantity_available = quantity_available - v_quantity,
          in_stock = (quantity_available - v_quantity) > 0
      where id = v_product.id;
  end loop;

  if nullif(btrim(coalesce(p_promo_code, '')), '') is not null then
    select * into v_promo
      from public.evaluate_promo_code(p_promo_code, v_customer_id, v_subtotal, true);
    if v_promo.error is not null then
      -- Rolls back everything above, stock included.
      raise exception 'PROMO_%', v_promo.error;
    end if;
    v_promo_id := v_promo.promo_id;
    v_promo_code := v_promo.code;
    v_discount := v_promo.discount;
  end if;

  v_total := v_subtotal - v_discount + c_delivery_fee;
  v_order_code := public.generate_order_code();

  insert into public.orders
    (order_code, customer_id, contact_phone, delivery_address_text,
     subtotal, delivery_fee, total_amount, status,
     promo_code_id, promo_code, discount_amount)
  values
    (v_order_code, v_customer_id, p_contact_phone, p_delivery_address_text,
     v_subtotal, c_delivery_fee, v_total, 'awaiting_confirmation',
     v_promo_id, v_promo_code, v_discount)
  returning id into v_order_id;

  insert into public.order_items
    (order_id, farmer_id, product_id, product_title, quantity, unit_type,
     unit_price, line_total, status)
  select v_order_id, f, p, t, q, u, up, lt, 'new'
  from unnest(
    v_farmer_ids, v_product_ids, v_titles, v_quantities,
    v_unit_types, v_unit_prices, v_line_totals
  ) as x(f, p, t, q, u, up, lt);

  insert into public.payments (order_id, bank_id, receipt_url, status)
  values (v_order_id, p_bank_id, p_receipt_url, 'pending');

  insert into public.order_status_events (order_id, status, changed_by, note)
  values (v_order_id, 'awaiting_confirmation', v_customer_id, 'Sifariş yaradıldı');

  return query select v_order_id, v_order_code;
end;
$$;

revoke execute on function public.place_order(text, text, uuid, text, jsonb, text)
  from public, anon;
grant execute on function public.place_order(text, text, uuid, text, jsonb, text)
  to authenticated;

-- ===== 043_checkout_details.sql =====
-- ---------------------------------------------------------------------------
-- Checkout asks for the recipient's name, the city and district, and an
-- optional note for the farmer or courier. They are stored on the order, so
-- the courier and the admin see who receives it and where, and the
-- customer's earlier addresses can be offered again next time.
-- ---------------------------------------------------------------------------

alter table public.orders
  add column if not exists recipient_first_name text
    check (recipient_first_name is null or char_length(recipient_first_name) between 1 and 50),
  add column if not exists recipient_last_name text
    check (recipient_last_name is null or char_length(recipient_last_name) between 1 and 50),
  add column if not exists delivery_city text
    check (delivery_city is null or char_length(delivery_city) between 1 and 60),
  add column if not exists delivery_district text
    check (delivery_district is null or char_length(delivery_district) <= 80),
  add column if not exists order_note text
    check (order_note is null or char_length(order_note) <= 500);

-- ---------------------------------------------------------------------------
-- place_order() with the new details. Same as migration 042 otherwise:
-- the customer comes from the session, the delivery fee from here, and the
-- promo code is judged in the same transaction.
-- ---------------------------------------------------------------------------
create or replace function public.place_order(
  p_contact_phone text,
  p_delivery_address_text text,
  p_bank_id uuid,
  p_receipt_url text,
  p_items jsonb,
  p_promo_code text,
  p_first_name text,
  p_last_name text,
  p_city text,
  p_district text,
  p_note text
)
returns table (order_id uuid, order_code text)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  c_delivery_fee constant numeric := 5;
  v_customer_id uuid := auth.uid();
  v_order_id uuid;
  v_order_code text;
  v_subtotal numeric := 0;
  v_discount numeric := 0;
  v_promo_id uuid;
  v_promo_code text;
  v_promo record;
  v_total numeric := 0;
  v_item jsonb;
  v_product record;
  v_quantity numeric;
  v_unit_price numeric;
  v_line_total numeric;
  v_farmer_ids uuid[] := '{}';
  v_product_ids uuid[] := '{}';
  v_titles text[] := '{}';
  v_quantities numeric[] := '{}';
  v_unit_types public.unit_type[] := '{}';
  v_unit_prices numeric[] := '{}';
  v_line_totals numeric[] := '{}';
begin
  if v_customer_id is null then
    raise exception 'NOT_SIGNED_IN';
  end if;

  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_CART';
  end if;

  -- Lock every involved product row up front, in a stable (id-sorted) order,
  -- so two concurrent checkouts touching an overlapping cart can't deadlock.
  perform 1
  from public.products
  where id in (
    select (value ->> 'product_id')::uuid
    from jsonb_array_elements(p_items)
  )
  order by id
  for update;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_quantity := (v_item ->> 'quantity')::numeric;
    if v_quantity is null or v_quantity <= 0 then
      raise exception 'INVALID_QUANTITY';
    end if;

    select id, farmer_id, title, unit_type, final_price, farmer_price,
           quantity_available, in_stock, status
      into v_product
      from public.products
      where id = (v_item ->> 'product_id')::uuid;

    if not found then
      raise exception 'PRODUCT_NOT_FOUND';
    end if;

    if v_product.status <> 'approved' then
      raise exception 'PRODUCT_NOT_FOUND';
    end if;

    if not v_product.in_stock or v_product.quantity_available < v_quantity then
      raise exception 'OUT_OF_STOCK:%', v_product.title;
    end if;

    v_unit_price := coalesce(v_product.final_price, v_product.farmer_price);
    v_line_total := v_unit_price * v_quantity;
    v_subtotal := v_subtotal + v_line_total;

    v_farmer_ids := v_farmer_ids || v_product.farmer_id;
    v_product_ids := v_product_ids || v_product.id;
    v_titles := v_titles || v_product.title;
    v_quantities := v_quantities || v_quantity;
    v_unit_types := v_unit_types || v_product.unit_type;
    v_unit_prices := v_unit_prices || v_unit_price;
    v_line_totals := v_line_totals || v_line_total;

    update public.products
      set quantity_available = quantity_available - v_quantity,
          in_stock = (quantity_available - v_quantity) > 0
      where id = v_product.id;
  end loop;

  if nullif(btrim(coalesce(p_promo_code, '')), '') is not null then
    select * into v_promo
      from public.evaluate_promo_code(p_promo_code, v_customer_id, v_subtotal, true);
    if v_promo.error is not null then
      -- Rolls back everything above, stock included.
      raise exception 'PROMO_%', v_promo.error;
    end if;
    v_promo_id := v_promo.promo_id;
    v_promo_code := v_promo.code;
    v_discount := v_promo.discount;
  end if;

  v_total := v_subtotal - v_discount + c_delivery_fee;
  v_order_code := public.generate_order_code();

  insert into public.orders
    (order_code, customer_id, contact_phone, delivery_address_text,
     subtotal, delivery_fee, total_amount, status,
     promo_code_id, promo_code, discount_amount,
     recipient_first_name, recipient_last_name, delivery_city,
     delivery_district, order_note)
  values
    (v_order_code, v_customer_id, p_contact_phone, p_delivery_address_text,
     v_subtotal, c_delivery_fee, v_total, 'awaiting_confirmation',
     v_promo_id, v_promo_code, v_discount,
     nullif(btrim(p_first_name), ''), nullif(btrim(p_last_name), ''),
     nullif(btrim(p_city), ''), nullif(btrim(p_district), ''),
     nullif(btrim(p_note), ''))
  returning id into v_order_id;

  insert into public.order_items
    (order_id, farmer_id, product_id, product_title, quantity, unit_type,
     unit_price, line_total, status)
  select v_order_id, f, p, t, q, u, up, lt, 'new'
  from unnest(
    v_farmer_ids, v_product_ids, v_titles, v_quantities,
    v_unit_types, v_unit_prices, v_line_totals
  ) as x(f, p, t, q, u, up, lt);

  insert into public.payments (order_id, bank_id, receipt_url, status)
  values (v_order_id, p_bank_id, p_receipt_url, 'pending');

  insert into public.order_status_events (order_id, status, changed_by, note)
  values (v_order_id, 'awaiting_confirmation', v_customer_id, 'Sifariş yaradıldı');

  return query select v_order_id, v_order_code;
end;
$$;

revoke execute on function public.place_order(text, text, uuid, text, jsonb, text, text, text, text, text, text)
  from public, anon;
grant execute on function public.place_order(text, text, uuid, text, jsonb, text, text, text, text, text, text)
  to authenticated;

-- The six-argument version from migration 042 stays for now, as a thin
-- wrapper, so the live site keeps taking orders in the minutes between this
-- migration and the deploy that sends the new details. A later migration
-- can drop it.
create or replace function public.place_order(
  p_contact_phone text,
  p_delivery_address_text text,
  p_bank_id uuid,
  p_receipt_url text,
  p_items jsonb,
  p_promo_code text default null
)
returns table (order_id uuid, order_code text)
language sql
security definer
set search_path = public, pg_temp
as $$
  select * from public.place_order(
    p_contact_phone, p_delivery_address_text, p_bank_id, p_receipt_url,
    p_items, p_promo_code, null::text, null::text, null::text, null::text, null::text
  );
$$;

-- ===== 044_order_item_cancel_reason.sql =====
-- ---------------------------------------------------------------------------
-- A farmer can cancel their line of a paid order before handing it over,
-- and must say why. The reason is kept on the line, so the customer and the
-- admin (who settles the refund) see it next to the product. Lines cancelled
-- with the whole order keep a null reason.
-- ---------------------------------------------------------------------------

alter table public.order_items
  add column if not exists cancel_reason text
    check (cancel_reason is null or char_length(cancel_reason) between 1 and 500);

-- ===== 045_more_unit_types.sql =====
-- ---------------------------------------------------------------------------
-- More selling units: banka (jar), stəkan (glass) and dəstə (bunch). Jarred
-- pickles and jams, berries by the glass and herbs by the bunch were listed
-- as "ədəd" until now.
--
-- Numbered after 043/044, which are still on the pre branch.
-- ---------------------------------------------------------------------------

alter type public.unit_type add value if not exists 'jar';
alter type public.unit_type add value if not exists 'glass';
alter type public.unit_type add value if not exists 'bunch';

-- ===== 046_unit_sizes.sql =====
-- ---------------------------------------------------------------------------
-- Package sizes: a jar of 0,5 kq or 1 kq, a glass of 10 qr or 25 qr, a whole
-- bird of 1–1,3 kq. The unit says how it is sold, the size how big one is.
-- The app offers a fixed list per unit (UNIT_SIZES in src/lib/shop/format.ts).
--
-- Order lines keep the size they were bought in, copied from the product when
-- the line is created, so a later edit of the product doesn't rewrite
-- history. A trigger does it, so place_order() needs no change.
-- ---------------------------------------------------------------------------

alter table public.products
  add column if not exists unit_size text
    check (unit_size is null or char_length(unit_size) between 1 and 30);

alter table public.order_items
  add column if not exists unit_size text
    check (unit_size is null or char_length(unit_size) between 1 and 30);

create or replace function public.order_items_copy_unit_size()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.unit_size is null then
    select p.unit_size into new.unit_size
      from public.products p
      where p.id = new.product_id;
  end if;
  return new;
end;
$$;

drop trigger if exists order_items_copy_unit_size on public.order_items;
create trigger order_items_copy_unit_size
before insert on public.order_items
for each row execute function public.order_items_copy_unit_size();

-- ===== 047_min_order_quantity.sql =====
-- ---------------------------------------------------------------------------
-- The smallest amount a customer may order of a product, set by the farmer:
-- 0,5 kq of cheese, 1 kq of honey. Null means the site's own floor for the
-- unit (50 qr, 0,5 l or one piece), which the app applies; amounts move in
-- the same steps (src/lib/shop/quantity.ts).
-- ---------------------------------------------------------------------------

alter table public.products
  add column if not exists min_order_quantity numeric(10, 2)
    check (min_order_quantity is null or min_order_quantity > 0);

-- ===== 048_lock_privileged_columns.sql =====
-- ---------------------------------------------------------------------------
-- Row-level policies say whose rows a user may update, not which columns.
-- With the public API key anyone signed in could, from the browser:
--   * make themselves admin (profiles.role), or sign up with role "admin";
--   * approve their own farm or products, set a product's final price;
--   * rewrite prices and totals on order lines and orders;
--   * send notifications to anyone and add events to any order.
-- The app never does these, but the database allowed them. Below, triggers
-- refuse such changes unless they come from an admin or from the server
-- (service role, or a security definer function such as place_order), and
-- the two insert policies are narrowed to the roles that use them.
-- ---------------------------------------------------------------------------

-- True for admins and for anything not running as a signed-in API user:
-- the service role, the SQL editor, and security definer functions (which
-- run as their owner). Deliberately not security definer itself, so
-- current_user is the caller's.
create or replace function public.is_privileged_writer()
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select current_user not in ('anon', 'authenticated') or public.is_admin();
$$;

-- ---------------------------------------------------------------------------
-- Sign-up: the role comes from here, never from what the client sends. The
-- app always signs people up as customers; admins promote them later.
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, role, full_name, email, phone)
  values (
    new.id,
    'customer'::public.user_role,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.email,
    new.phone
  );

  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- profiles: users edit their name and phone, never their role.
-- ---------------------------------------------------------------------------
create or replace function public.guard_profiles_update()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if not public.is_privileged_writer()
     and (new.role is distinct from old.role or new.id is distinct from old.id) then
    raise exception 'NOT_ALLOWED: role';
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_guard_update on public.profiles;
create trigger profiles_guard_update
before update on public.profiles
for each row execute function public.guard_profiles_update();

-- ---------------------------------------------------------------------------
-- farmers: a farmer applies as pending and proposes profile edits in the
-- pending_* columns; the admin approves both.
-- ---------------------------------------------------------------------------
create or replace function public.guard_farmers_write()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if public.is_privileged_writer() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.status := 'pending';
    new.verified_at := null;
    return new;
  end if;

  if new.status is distinct from old.status
     or new.verified_at is distinct from old.verified_at
     or new.profile_id is distinct from old.profile_id
     or new.description is distinct from old.description
     or new.location_text is distinct from old.location_text
     or new.location_lat is distinct from old.location_lat
     or new.location_lng is distinct from old.location_lng
     or new.location_map_url is distinct from old.location_map_url
     or new.avatar_url is distinct from old.avatar_url
     or new.cover_url is distinct from old.cover_url then
    raise exception 'NOT_ALLOWED: farmer fields need admin approval';
  end if;
  return new;
end;
$$;

drop trigger if exists farmers_guard_write on public.farmers;
create trigger farmers_guard_write
before insert or update on public.farmers
for each row execute function public.guard_farmers_write();

-- ---------------------------------------------------------------------------
-- products: new and edited products wait for the admin, who alone sets the
-- final price. A farmer may take an approved product off sale and back.
-- ---------------------------------------------------------------------------
create or replace function public.guard_products_write()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if public.is_privileged_writer() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.status := 'pending';
    new.final_price := null;
    new.sold_count := 0;
    new.rating_average := null;
    new.rating_count := 0;
    return new;
  end if;

  if new.farmer_id is distinct from old.farmer_id
     or new.sold_count is distinct from old.sold_count
     or new.rating_average is distinct from old.rating_average
     or new.rating_count is distinct from old.rating_count then
    raise exception 'NOT_ALLOWED: product fields';
  end if;

  -- Only clearing the final price (an edit sends the product back to review).
  if new.final_price is distinct from old.final_price and new.final_price is not null then
    raise exception 'NOT_ALLOWED: final price';
  end if;

  if new.status is distinct from old.status
     and not (
       new.status = 'pending'
       or (old.status = 'approved' and new.status = 'archived')
       or (old.status = 'archived' and new.status = 'approved')
     ) then
    raise exception 'NOT_ALLOWED: product status';
  end if;
  return new;
end;
$$;

drop trigger if exists products_guard_write on public.products;
create trigger products_guard_write
before insert or update on public.products
for each row execute function public.guard_products_write();

-- ---------------------------------------------------------------------------
-- order_items: farmers and couriers move a line's status along its steps;
-- what was bought and for how much never changes.
-- ---------------------------------------------------------------------------
create or replace function public.guard_order_items_update()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_step text := old.status::text || '>' || new.status::text;
begin
  if public.is_privileged_writer() then
    return new;
  end if;

  if new.order_id is distinct from old.order_id
     or new.farmer_id is distinct from old.farmer_id
     or new.product_id is distinct from old.product_id
     or new.product_title is distinct from old.product_title
     or new.quantity is distinct from old.quantity
     or new.unit_type is distinct from old.unit_type
     or new.unit_size is distinct from old.unit_size
     or new.unit_price is distinct from old.unit_price
     or new.line_total is distinct from old.line_total
     or new.created_at is distinct from old.created_at then
    raise exception 'NOT_ALLOWED: order line fields';
  end if;

  if new.cancel_reason is distinct from old.cancel_reason and new.status <> 'cancelled' then
    raise exception 'NOT_ALLOWED: cancel reason';
  end if;

  if new.status is distinct from old.status then
    if public.is_courier() then
      if v_step not in ('ready>picked_up', 'awaiting_pickup>picked_up', 'picked_up>delivered') then
        raise exception 'NOT_ALLOWED: order line status';
      end if;
    elsif v_step not in (
      'new>accepted', 'accepted>preparing', 'preparing>ready', 'ready>awaiting_pickup',
      'new>cancelled', 'accepted>cancelled', 'preparing>cancelled', 'ready>cancelled'
    ) then
      raise exception 'NOT_ALLOWED: order line status';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists order_items_guard_update on public.order_items;
create trigger order_items_guard_update
before update on public.order_items
for each row execute function public.guard_order_items_update();

-- ---------------------------------------------------------------------------
-- orders: couriers take an order and move its status; the money, the
-- customer and the delivery details stay as placed.
-- ---------------------------------------------------------------------------
create or replace function public.guard_orders_update()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if public.is_privileged_writer() then
    return new;
  end if;

  if new.customer_id is distinct from old.customer_id
     or new.order_code is distinct from old.order_code
     or new.subtotal is distinct from old.subtotal
     or new.delivery_fee is distinct from old.delivery_fee
     or new.total_amount is distinct from old.total_amount
     or new.discount_amount is distinct from old.discount_amount
     or new.promo_code_id is distinct from old.promo_code_id
     or new.promo_code is distinct from old.promo_code
     or new.contact_phone is distinct from old.contact_phone
     or new.delivery_address_text is distinct from old.delivery_address_text
     or new.recipient_first_name is distinct from old.recipient_first_name
     or new.recipient_last_name is distinct from old.recipient_last_name
     or new.delivery_city is distinct from old.delivery_city
     or new.delivery_district is distinct from old.delivery_district
     or new.order_note is distinct from old.order_note
     or new.created_at is distinct from old.created_at then
    raise exception 'NOT_ALLOWED: order fields';
  end if;
  return new;
end;
$$;

drop trigger if exists orders_guard_update on public.orders;
create trigger orders_guard_update
before update on public.orders
for each row execute function public.guard_orders_update();

-- ---------------------------------------------------------------------------
-- Notifications and order events are written by admins, couriers and
-- farmers (about their own lines); customers only get them.
-- ---------------------------------------------------------------------------
drop policy if exists "System inserts notifications for authenticated users" on public.notifications;
drop policy if exists "Staff insert notifications" on public.notifications;
create policy "Staff insert notifications"
on public.notifications for insert
with check (
  user_id = auth.uid()
  or public.is_admin()
  or public.is_courier()
  or public.current_user_role() = 'farmer'::public.user_role
);

drop policy if exists "Authenticated users insert status events" on public.order_status_events;
drop policy if exists "Staff insert status events" on public.order_status_events;
create policy "Staff insert status events"
on public.order_status_events for insert
with check (
  public.is_admin()
  or public.is_courier()
  or exists (
    select 1 from public.order_items oi
    where oi.order_id = order_status_events.order_id
      and public.is_farmer_owner(oi.farmer_id)
  )
);

-- ---------------------------------------------------------------------------
-- The six-argument place_order() kept by migration 043 for the minutes
-- between that migration and its deploy; the site only calls the new one.
-- ---------------------------------------------------------------------------
drop function if exists public.place_order(text, text, uuid, text, jsonb, text);

-- ===== 049_farmer_name_function.sql =====
-- ---------------------------------------------------------------------------
-- Farms are shown by the farmer's own name; farm names are going away
-- (050 drops the columns). Profiles are private, so the name is read
-- through this function: PostgREST treats it as a column of farmers, e.g.
--   farmers ( id, name:owner_name )
-- It returns only the name, and only for farmers anyone may see anyway.
--
-- Run this before deploying the code that reads it; farm_name stops being
-- required here so the new sign-up, which no longer asks for it, works
-- before 050 removes the column.
-- ---------------------------------------------------------------------------

-- Looks the farmer up by id rather than trusting the row it is handed, so a
-- direct call can't read an arbitrary profile: only approved farmers, the
-- farmer themselves and admins get a name.
create or replace function public.owner_name(public.farmers)
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p.full_name
  from public.farmers f
  join public.profiles p on p.id = f.profile_id
  where f.id = $1.id
    and (f.status = 'approved' or f.profile_id = auth.uid() or public.is_admin());
$$;

grant execute on function public.owner_name(public.farmers) to anon, authenticated;

alter table public.farmers alter column farm_name drop not null;

-- ===== 050_drop_farm_name.sql =====
-- ---------------------------------------------------------------------------
-- Farm names are gone from the site; farmers are shown by their own name
-- (owner_name(), migration 049). Run this after the code that no longer
-- reads farm_name is deployed.
-- ---------------------------------------------------------------------------

-- Where migration 048 is in place its farmers guard compares farm_name, and
-- would fail on every farmer update once the column is gone. Replace it
-- first; where 048 hasn't run yet there is nothing to replace.
do $do$
begin
  if to_regprocedure('public.guard_farmers_write()') is not null then
    execute $fn$
      create or replace function public.guard_farmers_write()
      returns trigger
      language plpgsql
      set search_path = public, pg_temp
      as $body$
      begin
        if public.is_privileged_writer() then
          return new;
        end if;

        if tg_op = 'INSERT' then
          new.status := 'pending';
          new.verified_at := null;
          return new;
        end if;

        if new.status is distinct from old.status
           or new.verified_at is distinct from old.verified_at
           or new.profile_id is distinct from old.profile_id
           or new.description is distinct from old.description
           or new.location_text is distinct from old.location_text
           or new.location_lat is distinct from old.location_lat
           or new.location_lng is distinct from old.location_lng
           or new.location_map_url is distinct from old.location_map_url
           or new.avatar_url is distinct from old.avatar_url
           or new.cover_url is distinct from old.cover_url then
          raise exception 'NOT_ALLOWED: farmer fields need admin approval';
        end if;
        return new;
      end;
      $body$;
    $fn$;
  end if;
end;
$do$;

alter table public.farmers drop column if exists farm_name;
alter table public.farmers drop column if exists pending_farm_name;

-- Replaced by owner_name().
drop function if exists public.list_approved_farmer_owner_names();

-- ===== 051_revoke_trigger_function_execute.sql =====
-- ---------------------------------------------------------------------------
-- These SECURITY DEFINER functions only run as triggers, but like every
-- function they were executable by PUBLIC, so anon and signed-in users could
-- reach them at /rest/v1/rpc/... (Supabase advisor). Triggers don't need
-- EXECUTE on their function, so taking it away changes nothing for them.
-- ---------------------------------------------------------------------------
revoke execute on function public.handle_new_user() from public, anon, authenticated;
revoke execute on function public.increment_product_sold_count() from public, anon, authenticated;
revoke execute on function public.cascade_cancel_order_items() from public, anon, authenticated;
revoke execute on function public.order_items_copy_unit_size() from public, anon, authenticated;
revoke execute on function public.product_reviews_refresh_rating() from public, anon, authenticated;
revoke execute on function public.site_reviews_before_write() from public, anon, authenticated;

-- ===== 20261025115108_farmer_payouts.sql =====
-- Farmer payout card (where Barakatly sends the farmer's share)
create table public.farmer_payout_accounts (
  id uuid primary key default gen_random_uuid(),
  farmer_id uuid not null unique references public.farmers(id) on delete cascade,
  bank_name text not null,
  pan_number text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- One payout per farmer per order
create table public.farmer_payouts (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders(id) on delete restrict,
  farmer_id uuid not null references public.farmers(id) on delete restrict,
  amount numeric(12,2) not null default 0,
  bank_name text,
  pan_number text,
  status text not null default 'pending' check (status in ('pending','paid')),
  paid_at timestamptz,
  paid_by uuid references public.profiles(id),
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (order_id, farmer_id)
);
create index farmer_payouts_status_idx on public.farmer_payouts(status);
create index farmer_payouts_farmer_idx on public.farmer_payouts(farmer_id);

-- Lines the payout is made of (farmer price snapshot)
create table public.farmer_payout_items (
  id uuid primary key default gen_random_uuid(),
  payout_id uuid not null references public.farmer_payouts(id) on delete cascade,
  order_item_id uuid references public.order_items(id) on delete set null,
  product_id uuid,
  product_title text not null,
  unit_type text,
  unit_size text,
  quantity numeric(12,3) not null,
  farmer_unit_price numeric(12,2) not null,
  line_total numeric(12,2) not null,
  created_at timestamptz not null default now()
);
create index farmer_payout_items_payout_idx on public.farmer_payout_items(payout_id);

-- RLS: admins everything, a farmer only reads their own rows
alter table public.farmer_payout_accounts enable row level security;
alter table public.farmer_payouts enable row level security;
alter table public.farmer_payout_items enable row level security;

create policy "Admins manage payout accounts" on public.farmer_payout_accounts
  for all using (public.is_admin()) with check (public.is_admin());
create policy "Farmers view own payout account" on public.farmer_payout_accounts
  for select using (public.is_farmer_owner(farmer_id));

create policy "Admins manage payouts" on public.farmer_payouts
  for all using (public.is_admin()) with check (public.is_admin());
create policy "Farmers view own payouts" on public.farmer_payouts
  for select using (public.is_farmer_owner(farmer_id));

create policy "Admins manage payout items" on public.farmer_payout_items
  for all using (public.is_admin()) with check (public.is_admin());
create policy "Farmers view own payout items" on public.farmer_payout_items
  for select using (exists (
    select 1 from public.farmer_payouts fp
    where fp.id = farmer_payout_items.payout_id and public.is_farmer_owner(fp.farmer_id)));

-- updated_at
create or replace function public.touch_updated_at() returns trigger
language plpgsql set search_path = public as $$
begin new.updated_at := now(); return new; end $$;

create trigger farmer_payout_accounts_touch before update on public.farmer_payout_accounts
  for each row execute function public.touch_updated_at();
create trigger farmer_payouts_touch before update on public.farmer_payouts
  for each row execute function public.touch_updated_at();

-- Build payouts for an order (idempotent: skips farmers that already have one)
create or replace function public.create_farmer_payouts(p_order_id uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare
  f record;
  v_payout uuid;
  v_count integer := 0;
begin
  for f in
    select distinct oi.farmer_id
    from order_items oi
    where oi.order_id = p_order_id and oi.status <> 'cancelled'
      and not exists (select 1 from farmer_payouts fp where fp.order_id = p_order_id and fp.farmer_id = oi.farmer_id)
  loop
    insert into farmer_payouts (order_id, farmer_id, bank_name, pan_number)
    select p_order_id, f.farmer_id, a.bank_name, a.pan_number
    from (select 1) x
    left join farmer_payout_accounts a on a.farmer_id = f.farmer_id and a.is_active
    returning id into v_payout;

    insert into farmer_payout_items (payout_id, order_item_id, product_id, product_title, unit_type, unit_size, quantity, farmer_unit_price, line_total)
    select v_payout, oi.id, oi.product_id, oi.product_title, oi.unit_type::text, oi.unit_size, oi.quantity,
           coalesce(p.farmer_price, 0), round(oi.quantity * coalesce(p.farmer_price, 0), 2)
    from order_items oi left join products p on p.id = oi.product_id
    where oi.order_id = p_order_id and oi.farmer_id = f.farmer_id and oi.status <> 'cancelled';

    update farmer_payouts
       set amount = (select coalesce(sum(line_total), 0) from farmer_payout_items where payout_id = v_payout)
     where id = v_payout;
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;

revoke all on function public.create_farmer_payouts(uuid) from public, anon, authenticated;

-- Fire when a payment becomes confirmed
create or replace function public.payments_create_farmer_payouts() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'confirmed' and (tg_op = 'INSERT' or old.status is distinct from 'confirmed') then
    perform public.create_farmer_payouts(new.order_id);
  end if;
  return new;
end $$;

create trigger payments_farmer_payouts
  after insert or update of status on public.payments
  for each row execute function public.payments_create_farmer_payouts();

